def clean(df):
    df = df.copy()
    df = df.drop_duplicates()

    allowed_categories = ["Electronics", "Accessories", "Furniture", "Office Supplies"]
    category_variants = {
        "accessories": "Accessories",
        "furnture": "Furniture",
        "office supplies": "Office Supplies",
    }

    def normalize_category(value):
        if pd.isna(value):
            return value
        text = str(value).strip()
        lowered = text.lower()
        if lowered in category_variants:
            return category_variants[lowered]
        for category in allowed_categories:
            if lowered == category.lower():
                return category
        return text

    if "Category" in df.columns:
        df["Category"] = df["Category"].map(normalize_category)

    return df

def answer(df):
    cleaned = clean(df)
    averages = cleaned.groupby("Category", dropna=True)["Price"].mean()
    return {str(label): float(value) for label, value in sorted(averages.items())}
